import React, { useState, useEffect } from "react";
import axios from "axios";
import { animate } from "./app.ts";
import "./WeatherComponent.css"; // 引入样式
import { windImp } from "./app";
let mediaElement: Audio;
const WeatherComponent = () => {
  const [weatherData, setWeatherData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [windLevel, setWindLevel] = useState(null);
  const [latitude, setLatitude] = useState(39.9042); // Default: Beijing
  const [longitude, setLongitude] = useState(116.4074); // Default: Beijing

  // 快速设置按钮的城市信息
  const cities = {
    shanghai: { lat: 31.2304, lon: 121.4737 },
    纽约: { lat: 74, lon: 40.43 },
    dongying: { lat: 37.4343, lon: 118.6857 },
    haidian: { lat: 39.9570, lon: 116.3075 },
  };
  const getWindDirection = (degree) => {
    const directions = [
      "北风 (North)", "东北风 (Northeast)", "东风 (East)", "东南风 (Southeast)",
      "南风 (South)", "西南风 (Southwest)", "西风 (West)", "西北风 (Northwest)"
    ];
    return directions[Math.round(degree / 45) % 8] || "未知方向";
  };

  // 转换开尔文到摄氏度
  const kelvinToCelsius = (kelvin) => {
    return (kelvin - 273.15).toFixed(2); // 保留两位小数
  };



  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await axios.get(
          `https://api.openweathermap.org/data/2.5/weather?lat=${latitude}&lon=${longitude}&appid=7749ab343a0f2c1e02c676ee8ac2f822`
        );

        // 更新风速及风力级别
        const windSpeed = response.data.wind.speed;
        windImp(windSpeed);
        const level = getWindLevel(windSpeed);
        setWindLevel(level);

        // 更新天气数据
        setWeatherData(response.data);

        animate(response.data); // 调用 animate.ts
        setLoading(false);
      } catch (error) {
        setError(error);
        setLoading(false);
      }
    };

    fetchData();
  }, [latitude, longitude]); // 监听经纬度变化，触发数据重新获取

  // function music() {
  //   const file = 'sound/rain.mp3';
  //   mediaElement = new Audio(file);
  //   mediaElement.play();
  // }



  const getWindLevel = (windSpeed) => {
 
    if (windSpeed >= 0 && windSpeed < 0.6) {
      return "1级：轻风";
    } else if (windSpeed >= 0.6 && windSpeed < 1.6) {
      return "2级：和风";
    } else if (windSpeed >= 1.6 && windSpeed < 3.4) {
      return "3级：微风";
    } else if (windSpeed >= 3.4 && windSpeed < 5.5) {
      return "4级：清风";
    } else if (windSpeed >= 5.5 && windSpeed < 8.0) {
      return "5级：强风";
    } else if (windSpeed >= 8.0 && windSpeed < 10.8) {
      return "6级：劲风";
    } else if (windSpeed >= 10.8 && windSpeed < 13.9) {
      return "7级：疾风";
    } else if (windSpeed >= 13.9 && windSpeed < 17.2) {
      return "8级：大风";
    } else if (windSpeed >= 17.2 && windSpeed < 20.8) {
      return "9级：烈风";
    } else if (windSpeed >= 20.8 && windSpeed < 24.5) {
      return "10级：暴风";
    } else {
      return "11级：狂风";
    }
  };


  const handleCitySelect = (city) => {
    setLatitude(cities[city].lat);
    setLongitude(cities[city].lon);
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>Error occurred: {error.message}</div>;
  }

  return (
    <div className="weather-container">
      <h3>国家 {weatherData.sys.country} {weatherData.name}</h3>
      <p>天气:
        {weatherData.weather[0].description + ' '}
        风力: {windLevel} </p>
      <p>温度: {kelvinToCelsius(weatherData.main.temp)} °C
        体感: {kelvinToCelsius(weatherData.main.feels_like)} °C  </p>
      <p>湿度: {weatherData.main.humidity}%</p>


      {/* 选择城市的按钮 */}
      <div className="city-selector">
        <button onClick={() => handleCitySelect('shanghai')}>上海</button>
        <button onClick={() => handleCitySelect('纽约')}>纽约</button>
        <button onClick={() => handleCitySelect('dongying')}>东营</button>
        <button onClick={() => handleCitySelect('haidian')}>海淀</button>

        {/* <button id="playButton" onClick={() => mediaElement.play()}>
        ▶ 播放音乐
      </button> */}
      </div>
      {/* 可选择的经纬度输入框 */}
      <div className="coordinates-input">
        <label>
          经度:
          <input
            type="number"
            value={longitude}
            onChange={(e) => setLongitude(parseFloat(e.target.value))}
          />
        </label>
        <label>
          纬度:
          <input
            type="number"
            value={latitude}
            onChange={(e) => setLatitude(parseFloat(e.target.value))}
          />
        </label>
      </div>

      <h2>Weather Information</h2>
      {/* <p>
        Coordinates: {weatherData.coord.lon}, {weatherData.coord.lat}
      </p> */}
      <p id='weatherid'>
        Weather: {weatherData.weather[0].main} -{" "}
        {weatherData.weather[0].description}
      </p>
      <p>温度: {kelvinToCelsius(weatherData.main.temp)} °C</p>
      <p>体感温度: {kelvinToCelsius(weatherData.main.feels_like)} °C </p>
      <p>最低温度: {kelvinToCelsius(weatherData.main.temp_min)}  °C</p>
      <p>最高温度: {kelvinToCelsius(weatherData.main.temp_max)}  °C</p>
      <p>Pressure: {weatherData.main.pressure} hPa</p>
      <p>湿度: {weatherData.main.humidity}%</p>
      <p>可见度: {weatherData.visibility} 米</p>
      <p>
        风速: {weatherData.wind.speed} m/s, 风向:{" "}
        {getWindDirection(weatherData.wind.deg)}{weatherData.wind.deg}°,

        阵风: {weatherData.wind.gust ? `${weatherData.wind.gust} m/s` : "无"}


      </p>
      <p>云量: {weatherData.clouds.all}%</p>
      <p>Date/Time: {new Date(weatherData.dt * 1000).toLocaleString()}</p>
      <p>Country: {weatherData.sys.country}</p>
      <p>
        日出: {new Date(weatherData.sys.sunrise * 1000).toLocaleTimeString()}
      </p>
      <p>
        日落: {new Date(weatherData.sys.sunset * 1000).toLocaleTimeString()}
      </p>
      <p>Timezone: {weatherData.timezone}</p>
      <p>City ID: {weatherData.id}</p>
      <p>City Name: {weatherData.name}</p>
    </div>
  );
};

export default WeatherComponent;
