function getRain() {
  if (rainStarted) return;
  rainStarted = true;

  rainDrop = new RainDrop();
  rainDrop.instance.name = "rain";
  scene.add(rainDrop.instance);

}
function loadFlash() {
  if (cloudStarted) return;
  cloudStarted = true;

  for (let i = 0; i < 10; i++) {
    cloud = new Cloud();
    clouds.push(cloud);
    cloud.setPosition(
      Math.random() * 10 + 10,
      Math.random() * 20 + 60,
      -Math.random() * 10 - 2
    );
    cloud.setRotation(1.2, -0.32, Math.random() * 360);
    cloud.instance.name = i.toString();
    scene.add(cloud.instance);
  }
}
export const go = async () => {
  const gltfLeaf = await loader.loadAsync("assets/leaf/scene.gltf");
  leafModel = gltfLeaf.scene.clone();
  leafModel.name = "leaf";
  leafModel.castShadow = true;
  leafModel.receiveShadow = true;
  crment();
  init();
  createTree();
  // getRain();
  // loadFlash();
  animate('0');
};
export const windImp = async (windSpeed: number) => {
  // ...

  if (windSpeed >= 0 && windSpeed < 1) {
    windLevel = 0.01;
    Level = 1;
  } else if (windSpeed >= 1 && windSpeed < 2) {
    Level = 2;
    windLevel = 0.05;
  } else if (windSpeed >= 2 && windSpeed < 3) {
    Level = 3;
    windLevel = 0.09;
  } else if (windSpeed >= 3 && windSpeed < 4) {
    Level = 4;
    windLevel = 0.2;
  } else if (windSpeed >= 4 && windSpeed < 5) {
    Level = 5;
    windLevel = 0.5;
  } else {
    Level = 5;
    windLevel = 0.4;
  }
};
function crment() {
  return "123";
}

// const webGPUUtils = new WebGPUUtils();
const init = () => {
  scene = new Scene();
  scene.background = new Color(0xffffff); //背景色

  // LIGHTS
  const hemisphereLightColour = new Color().setHSL(0.6, 1, 0.6);
  addHemisphereLight(hemisphereLightColour, scene);
  addDirectionalLight(scene);

  // GROUND
  const groundGeo = new PlaneGeometry(1000, 1000);
  groundMaterial = new MeshLambertMaterial({ color: options.groundColour });

  const ground = new Mesh(groundGeo, groundMaterial);
  ground.position.y = -40;
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);

  //RENDERER
  renderer = new WebGLRenderer({
    antialias: window.devicePixelRatio === 1,
    powerPreference: "high-performance",
  });
  // renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setSize(window.innerWidth, window.innerHeight);
  // renderer.setSize(720, 360);
  renderer.setPixelRatio(window.devicePixelRatio);
  renderer.outputEncoding = sRGBEncoding;
  renderer.shadowMap.enabled = true;
  document.body.appendChild(renderer.domElement);

  stats = new (Stats as any)();
  // document.body.appendChild(stats.dom);

  camera = new PerspectiveCamera(
    30,
    // window.innerWidth / window.innerHeight,
    window.innerWidth * 0.8 / (window.innerHeight * 0.9),
    // 720 / 360,
    1,
    500
  );
  camera.position.set(0, 100, 200);

  orbitControls = new OrbitControls(camera, renderer.domElement);

  transformControls = new TransformControls(camera, renderer.domElement);
  scene.add(transformControls);
  transformControls.addEventListener("mouseDown", function () {
    orbitControls.enabled = false;
  });
  transformControls.addEventListener("mouseUp", function () {
    orbitControls.enabled = true;
  });

  window.addEventListener("keydown", function (event) {
    switch (event.key.toUpperCase()) {
      case "R":
        transformControls.setMode("rotate");
        break;
      case "V":
        transformControls.setMode("translate");
        break;

      default:
        break;
    }
  });
};

function applyWindEffect(tree: Group) {
  if (Level > 4) {

    treeGroup.traverse((child) => {
      if (child instanceof Group) {
        if (child.name.includes("树干")) {

          child.rotation.x = MathUtils.degToRad(
            randomFloatFromInterval(-4, 4) * windLevel
          );
        } else {
          if (Math.random() > 0.6) {

            child.rotation.x = MathUtils.degToRad(
              randomFloatFromInterval(-10, 10) * windLevel
            );
          }
        }
      }
    });

  } else {
    treeGroup.traverse((child) => {
      if (child instanceof Group && child.children.length === 1) {
        const leaf = child.children[0];
        if (isLeaf(leaf) && Math.random() > 0.6) {


          updateLeafRotation(leaf);
        }
      }
    });
  }
}

function isLeaf(object: any): object is Group {
  return object instanceof Group;
}
function calculateWindEffect() {
  return 0.001 * ((Math.cos(clock.elapsedTime) + 1) / 2) * 50;
}
function updateLeafRotation(leaf: Group) {
  const rotationParent = leaf.parent as Group;
  // let ct = clock.getDelta();

  const newSeed = MathUtils.randInt(0, 10000);
  MathUtils.seededRandom(newSeed); // 设置新的种子

  const rx = MathUtils.degToRad(360 * MathUtils.seededRandom()) * windLevel;
  const rz = MathUtils.degToRad(360 * MathUtils.seededRandom()) * windLevel;

  const windEffectX = calculateWindEffect();
  rotationParent.rotation.x = rx + windEffectX;

  const windEffectZ = calculateWindEffect();
  rotationParent.rotation.z = rz + windEffectZ;
}

function createTree() {
  MathUtils.seededRandom(options.seed);


  scene.remove(treeGroup); // 使用treeGroup而不是tree
  treeGroup = new Group(); // 创建treeGroup
  makeTree(options.height, new Vector3(0, 0, 0), 0, 0, options.height / 10);
  scene.add(treeGroup); // 使用treeGroup而不是tree
  treeGroup.position.set(0, -40, 0);
}

function makeTree(
  length: number,
  pos: Vector3,
  rz: number,
  ry: number,
  rBottom: number = length / 20
) {
  const rTop = rBottom * 0.66;

  const group = new Group();
  const branchDirection = new Vector3(0, 1, 0);
  group.position.set(pos.x, pos.y, pos.z);

  if (length < options.minBranchLength) {
    addLeaf(group);
    treeGroup.add(group);
    return;
  }

  const branchColour = new Color()
    .setHex(options.treeColour)
    .offsetHSL(0, MathUtils.seededRandom() / 10, MathUtils.seededRandom() / 8);

  const branchSegment = createCylinder(rTop, rBottom, length, branchColour);
  num++;
  // branchSegment.name='树干'+num;
  group.add(branchSegment);
  group.name = "树干" + num;
  // tree.add(group);
  treeGroup.add(group);

  branchSegment.position.y += length / 2;

  group.rotation.z = rz;
  branchDirection.applyAxisAngle(new Vector3(0, 0, 1), rz);

  group.rotation.y = ry;
  branchDirection.applyAxisAngle(new Vector3(0, 1, 0), ry);

  branchDirection.multiplyScalar(length);

  const endOfBranchPos = pos.clone().add(branchDirection);

  const isLargerBranch = length > options.height / 3;
  const drawingTrunk = length === options.height;

  if (isLargerBranch && !drawingTrunk) {
    const knot = createSphere(rTop * 1.5, branchColour);
    group.add(knot);
  } else if (!drawingTrunk) {
    addLeaf(group);
    treeGroup.add(group);
  }

  const numberOfBranches = getNumberOfBranches();
  for (let i = 0; i < numberOfBranches; i++) {
    rz = MathUtils.degToRad(
      randomFloatFromInterval(-options.maxBranchAngle, options.maxBranchAngle)
    );
    ry = MathUtils.degToRad(
      randomFloatFromInterval(-options.maxBranchAngle, options.maxBranchAngle)
    );

    makeTree(
      length *
      MathUtils.mapLinear(
        options.minBranchLength,
        minBranchLengthRange[0],
        minBranchLengthRange[1],
        minBranchLengthRatioRange[0],
        minBranchLengthRatioRange[1]
      ),
      endOfBranchPos,
      rz,
      ry,
      rTop
    );
  }
}

export const animate = (weatherData: any = cachedWeatherData) => {

  requestAnimationFrame(() => animate(cachedWeatherData)); // 继续传递
  clock.getElapsedTime();

  applyWindEffect(treeGroup); // 使用treeGroup而不是tree

  if (!options.flyAround) {
    const radius = 200;
    camera.position.x =
      tree.position.x + radius * Math.cos(0.4 * clock.elapsedTime);
    camera.position.z =
      tree.position.z + radius * Math.sin(0.4 * clock.elapsedTime);
    camera.position.y =
      90 + (tree.position.y + 35 * Math.sin(0.2 * clock.elapsedTime));

    camera.lookAt(tree.position);
  }

  if (weatherData) {
    if (weatherData == "0") {
    } else {
      cachedWeatherData = weatherData; // 更新缓存
      console.log(`${weatherData?.weather?.[0]?.main || "No data"}`);
      // if (weatherData.weather[0].main.toLowerCase().includes("rain")) {
      if (weatherData.weather[0].main.toLowerCase().includes("rain")) {
          getRain();
          loadFlash();
        if (rainDrop) {
          rainDrop.animate();

          clouds.forEach((cloud) => {
            cloud.animate();
          });
        }



      } else {
        rainStarted = false;
        cloudStarted=false;
        scene.remove(scene.getObjectByName("rain"));
        for (var i = 0; i < 10; i++) {
          scene.remove(scene.getObjectByName(i.toString()));
        }
      }
    }
  }


  orbitControls.update();

  stats.update();
  renderer.render(scene, camera);
};

function getNumberOfBranches() {
  const rnd = MathUtils.seededRandom();
  return rnd < 1 - options.branchDensity
    ? randomIntFromInterval(1, 2)
    : randomIntFromInterval(3, 4);
}

function addLeaf(group: Group) {
  const scale = options.leafSize * MathUtils.seededRandom();
  const rx = MathUtils.degToRad(360 * MathUtils.seededRandom());
  const rz = MathUtils.degToRad(360 * MathUtils.seededRandom());

  const leafColour = new Color()
    .setHex(options.leafColour)
    .offsetHSL(
      MathUtils.seededRandom() / 10,
      MathUtils.seededRandom() / 10,
      MathUtils.seededRandom() / 8
    );

  if (!options.hasLeaves) {
    return;
  }

  const leaf = leafModel.clone();
  leaf.rotation.setFromVector3(new Vector3(0, 0, 0));

  const bbox = new Box3().setFromObject(leaf);
  const center = bbox.getCenter(new Vector3());
  const size = bbox.getSize(new Vector3());
  leaf.scale.set(scale, scale, scale);

  bbox.setFromObject(leaf);
  bbox.getCenter(center);
  bbox.getSize(size);

  var box = new Box3().setFromObject(leaf);
  box.getCenter(leaf.position); // this re-sets the leaf position
  leaf.position.add(new Vector3(0, 0, size.z / 2));
  leaf.position.multiplyScalar(-1);

  leaf.position.copy(center).multiplyScalar(-1);

  let rotationParent = new Group();
  rotationParent.add(leaf);

  leaf.position.z -= size.z * 0.45;
  leaf.position.x += size.x * 0.0075;
  leaf.position.y += size.y * 0.01;

  rotationParent.rotation.x = rx;
  rotationParent.rotation.z = rz;

  leaf.traverse(function (child) {
    if (child as Mesh) {
      var newMaterial = new MeshLambertMaterial({
        color: leafColour,
      });
      (child as Mesh).material = newMaterial;

      child.castShadow = true;
      child.receiveShadow = true;
    }
  });

  group.add(rotationParent);
}


function randomIntFromInterval(min: number, max: number) {
  // min and max included
  return Math.floor(MathUtils.seededRandom() * (max - min + 1) + min);
}

function randomFloatFromInterval(min: number, max: number) {
  return MathUtils.seededRandom() * (max - min) + min;
}
