import "./index.css";
import React from "react";
import ReactDOM from "react-dom";
import * as app from "./trees/app";
import WeatherComponent from './trees/WeatherComponent'; 



const App = () => {
  return (
    <div>

      <WeatherComponent />
      <div id="app"></div>
    </div>
  );
};

ReactDOM.render(<App />, document.getElementById("root"));
app.go();


